import { useEffect,useMemo,useState } from "react"
import type { FormEvent } from "react"
import type { RouteConfig } from "@mercurjs/dashboard-sdk"
import { Actions,Button,Card,Field,FormGrid,Message,Page,PageHeader } from "../../spike/ui"
import {Input} from "../../components/ui/input"
import {Textarea} from "../../components/ui/textarea"
import {Select} from "../../components/ui/select"
declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"إضافة منتج",rank:19}
type Category={id:string;name?:string;title?:string};type FormState={title:string;description:string;category_id:string;image_url:string;price:string;quantity:string;sku:string;returnable:string}
const initial:FormState={title:"",description:"",category_id:"",image_url:"",price:"",quantity:"0",sku:"",returnable:""}
const base=()=>String(__BACKEND_URL__||"http://localhost:9000").replace(/\/$/,"");async function api(p:string,i?:RequestInit){const r=await fetch(base()+p,{credentials:"include",...i,headers:{...(i?.body?{"content-type":"application/json"}:{}),...(i?.headers||{})}});const t=await r.text();let d:any={};try{d=t?JSON.parse(t):{}}catch{}if(!r.ok)throw new Error(d.message||t||`HTTP ${r.status}`);return d}
const makeSku=(title:string)=>`SPK-${title.normalize("NFKD").replace(/[^a-zA-Z0-9\u0600-\u06FF]+/g,"-").replace(/^-+|-+$/g,"").slice(0,18).toUpperCase()||"ITEM"}-${Date.now().toString().slice(-5)}`
export default function AddProduct(){const[form,setForm]=useState<FormState>(initial),[categories,setCategories]=useState<Category[]>([]),[loading,setLoading]=useState(false),[msg,setMsg]=useState(""),[error,setError]=useState("");const autoSku=useMemo(()=>form.sku||makeSku(form.title),[form.sku,form.title]);const set=(k:keyof FormState,v:string)=>setForm(x=>({...x,[k]:v}));useEffect(()=>{api('/vendor/product-categories?limit=100').then(d=>setCategories(d.product_categories||d.categories||[])).catch(()=>setCategories([]))},[]);const upload=async(file?:File|null)=>{if(!file)return;setLoading(true);setError("");try{const fd=new FormData();fd.append('files',file);const r=await fetch(`${base()}/vendor/uploads`,{method:'POST',credentials:'include',body:fd});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'تعذر رفع الصورة');const url=d?.files?.[0]?.url||d?.uploads?.[0]?.url||d?.file?.url;if(!url)throw new Error('تعذر حفظ الصورة');set('image_url',url)}catch(e:any){setError(e.message)}finally{setLoading(false)}};
const submit=async(e:FormEvent)=>{e.preventDefault();setLoading(true);setError('');setMsg('');try{if(!form.title.trim())throw new Error('اكتب اسم المنتج');if(!form.price||Number(form.price)<0)throw new Error('اكتب سعرًا صحيحًا');if(!form.returnable)throw new Error('حدد سياسة الإرجاع');const sku=form.sku.trim()||autoSku;const created=await api('/vendor/products?fields=id,title,*variants',{method:'POST',body:JSON.stringify({title:form.title.trim(),description:form.description.trim()||undefined,status:'proposed',categories:form.category_id?[{id:form.category_id}]:undefined,images:form.image_url?[{url:form.image_url}]:undefined,thumbnail:form.image_url||undefined,variants:[{title:'Default variant',sku}]})});const productId=created?.product?.id;if(!productId)throw new Error('لم يرجع النظام رقم المنتج');let variantId=created?.product?.variants?.[0]?.id;if(!variantId)variantId=(await api(`/vendor/products/${productId}?fields=id,*variants`))?.product?.variants?.[0]?.id;if(!variantId)throw new Error('تعذر العثور على نسخة المنتج');const profiles=await api('/vendor/shipping-profiles?limit=20');let shippingProfileId=profiles?.shipping_profiles?.[0]?.id;if(!shippingProfileId)shippingProfileId=(await api('/vendor/shipping-profiles',{method:'POST',body:JSON.stringify({name:'Spike Default',type:'default'})}))?.shipping_profile?.id;if(!shippingProfileId)throw new Error('تعذر تجهيز الشحن');let locationId:string|undefined;try{locationId=(await api('/vendor/stock-locations?limit=20'))?.stock_locations?.[0]?.id}catch{}const inventoryItem:any={title:form.title.trim(),sku,required_quantity:1};if(locationId)inventoryItem.stock_levels=[{location_id:locationId,stocked_quantity:Math.max(0,Math.floor(Number(form.quantity||0)))}];await api('/vendor/offers',{method:'POST',body:JSON.stringify({sku,variant_id:variantId,shipping_profile_id:shippingProfileId,inventory_items:[inventoryItem],prices:[{amount:Number(form.price),currency_code:'usd'}],manage_inventory:Boolean(locationId),allow_backorder:false})});try{await api('/vendor/spike/product-delivery',{method:'POST',body:JSON.stringify({product_id:productId,returnable:form.returnable==='yes',auto_assign:true})})}catch{}setMsg('تم إنشاء المنتج وإرساله للمراجعة. مكتب التوصيل يحدده النظام تلقائيًا حسب التغطية.');setForm(initial)}catch(e:any){setError(e.message||'حدث خطأ أثناء إنشاء المنتج')}finally{setLoading(false)}};
return <Page><PageHeader title="إضافة منتج" description="أدخل بيانات المنتج الأساسية. التسعير الأساسي بالدولار ومكتب التوصيل يختاره النظام تلقائيًا حسب التغطية."/>{error&&<Message>{error}</Message>}{msg&&<Message>{msg}</Message>}<form onSubmit={submit}><Card><h2>معلومات المنتج</h2><FormGrid><Field label="اسم المنتج *"><Input value={form.title} onChange={e=>set('title',e.target.value)} placeholder="اسم المنتج"/></Field><Field label="الفئة"><Select value={form.category_id} onValueChange={v=>set('category_id',v)} placeholder="بدون فئة" options={categories.map(c=>({value:c.id,label:c.name||c.title||c.id}))}/></Field><Field label="الوصف" wide><Textarea value={form.description} onChange={e=>set('description',e.target.value)} rows={4} placeholder="وصف مختصر وواضح"/></Field><Field label="صورة المنتج" wide><Input type="file" accept="image/*" disabled={loading} onChange={e=>void upload(e.target.files?.[0])}/>{form.image_url&&<div className="spike-upload-preview"><img src={form.image_url} alt="معاينة المنتج"/></div>}</Field></FormGrid></Card><Card><h2>السعر والمخزون</h2><FormGrid><Field label="سعر البيع بالدولار *"><Input type="number" min="0" step="0.01" value={form.price} onChange={e=>set('price',e.target.value)} placeholder="0.00"/></Field><Field label="الكمية"><Input type="number" min="0" step="1" value={form.quantity} onChange={e=>set('quantity',e.target.value)}/></Field><Field label="العملة"><Input readOnly value="USD — دولار أمريكي"/></Field><Field label="سياسة الإرجاع *"><Select value={form.returnable} onValueChange={v=>set('returnable',v)} placeholder="اختر" options={[{value:'yes',label:'قابل للإرجاع'},{value:'no',label:'غير قابل للإرجاع'}]}/></Field><Field label="SKU (اختياري — يتولد تلقائيًا)" wide><Input value={form.sku} onChange={e=>set('sku',e.target.value)} placeholder={autoSku}/></Field></FormGrid></Card><Actions><Button type="submit" disabled={loading}>{loading?'جاري إنشاء المنتج...':'حفظ المنتج'}</Button></Actions></form></Page>}
